key:
func twoSum(_ values: [Int], target: Int) -> (Int, Int)? {
    var seen: [Int: Int] = [:]
    for (index, value) in values.enumerated() {
        if let first = seen[target - value] { return (first, index) }
        seen[value] = index
    }
    return nil
}

Словарь отвечает «видели ли нужное дополнение?». Поиск до вставки не даёт использовать один элемент дважды; среднее время O(n).

func summarize(_ authors: [String]) -> ([String: Int], [String]) {
    var counts: [String: Int] = [:]
    var seen: Set<String> = []
    var names: [String] = []
    for author in authors {
        counts[author, default: 0] += 1
        if seen.insert(author).inserted { names.append(author) }
    }
    return (counts, names)
}

В среднем время O(n), дополнительная память O(k) для k разных авторов. Проверь пустой список и повторы в Swift Playground.
